/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_entityCtx">_entityCtx</param>
/// <param name = "_dataSourceCtx">_dataSourceCtx</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    super(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(AVASFCFeedbackEntity,AVASFCFeedback))
    {
        AVASFCFeedback      sfcFeedback = _dataSourceCtx.getBuffer();
        ProdTable           prodTable;
        WrkCtrTable         wrkCtrTable;

        prodTable = ProdTable::find(JmgJobTable::find(this.JmgJobIdOrig).ModuleRefId);

        sfcFeedback.ProdId     = prodTable.ProdId;
        if (this.TransactionType == AVASFCTransactionType::JobProcessing || this.TransactionType == AVASFCTransactionType::JobProcessing)
        {
            select firstonly wrkCtrTable
                where wrkCtrTable.KCS_BDEMachineNo == this.ResourceOrig;
            sfcFeedback.WrkCtrId   = wrkCtrTable.WrkCtrId;
        }

        container jobInfo = this.getActuallyJobId();

        sfcFeedback.JmgJobId = conPeek(jobInfo,1);
        sfcFeedback.JmgJobDescription = conPeek(jobInfo,2);

        JmgEmployee     jmgEmployee;
        HCMWorker       hcmWorker;

        select firstonly jmgEmployee    
            where jmgEmployee.LoginCardNo == this.EmplIdOrig
               join hcmWorker
               where hcmWorker.RecId == jmgEmployee.Worker;

        sfcFeedback.PersonnelNumber = hcmWorker.PersonnelNumber;
        sfcFeedback.Worker          = hcmWorker.RecId;


        sfcFeedback.DefaultDimension = prodTable.DefaultDimension;
        sfcFeedback.InventLocationId = prodTable.inventDim().inventSiteId;
        sfcFeedback.InventSiteId     = prodTable.inventDim().InventLocationId;
        sfcFeedback.JmgDate          = DateTimeUtil::date(this.JmgDateTime);

    }
}

/// <summary>
/// designed from AVA
/// </summary>
public container  getActuallyJobId()
{
    ProdRouteJob               prodRouteJob;
    JmgIpcActivity             jmgIpcActivity;
    JmgIpcCategory             jmgIpcCategory;
    container                  jobInfo;

    switch (this.TransactionType)
    {
        case AVASFCTransactionType::JobProcessing :
            jobInfo = conIns(jobInfo,1,this.JmgJobIdOrig);
            jobInfo = conIns(jobInfo,2,strFmt("@NDX:NXABDEProcessing"));
            break;

        case AVASFCTransactionType::JobSetup :
            select firstonly prodRouteJob
                 where prodRouteJob.ProdId  == this.ProdId
                    && prodRouteJob.JobType == RouteJobType::Setup;
            jobInfo = conIns(jobInfo,1,prodRouteJob.JobId);
            jobInfo = conIns(jobInfo,2,strFmt("@NDX:NDXSettings"));
            break;

        case AVASFCTransactionType::Interruption01 :
        case AVASFCTransactionType::Interruption02 :
        case AVASFCTransactionType::Interruption03 :
        case AVASFCTransactionType::Interruption04 :
        case AVASFCTransactionType::Interruption05 :
        case AVASFCTransactionType::Interruption06 :
        case AVASFCTransactionType::Interruption07 :
        case AVASFCTransactionType::Interruption08 :
        case AVASFCTransactionType::Interruption09 :
        case AVASFCTransactionType::Interruption10 :
        case AVASFCTransactionType::Interruption11 :
        case AVASFCTransactionType::Interruption12 :
        case AVASFCTransactionType::Interruption13 :
        case AVASFCTransactionType::Interruption14 :
        case AVASFCTransactionType::Interruption15 :
        case AVASFCTransactionType::Interruption16 :
        case AVASFCTransactionType::Interruption17 :
        case AVASFCTransactionType::Interruption18 :
        case AVASFCTransactionType::Interruption19 :
        case AVASFCTransactionType::Interruption20 :
            select firstonly jmgIpcActivity
                join jmgIpcCategory
                where jmgIpcCategory.Category == jmgIpcActivity.Category
                   && jmgIpcCategory.Type     == jmgIpcActivity.Type;  

            jobInfo = conIns(jobInfo,1,jmgIpcActivity.JobId);
            jobInfo = conIns(jobInfo,2,jmgIpcActivity.Description);
            break;
    }
    return jobInfo;
}
